SELECT
  json_extract(value, '$.family') AS "family",
  json_extract(value, '$.mapping') AS "mapping",
  json_extract(value, '$.boundary') AS "boundary"
FROM json_each('[{"family": "Anthropic / Claude", "mapping": "Separate Messages adapter; adaptive thinking and output_config.effort, or an explicit thinking budget", "boundary": "Version-specific accepted efforts and schemas; preserve thinking signatures on replay."}, {"family": "Cohere Command", "mapping": "thinking object; ReasoningTokens maps to token_budget", "boundary": "Code notes say disabling thinking was accepted but ignored in an earlier probe. Parse and Rerank are different operations."}, {"family": "DeepSeek", "mapping": "reasoning_effort for the current V4 mapping", "boundary": "Earlier code notes distinguish an honored effort field from an ignored thinking toggle; do not generalize across versions."}, {"family": "Microsoft / MAI-Thinking-1", "mapping": "reasoning_effort; explicit max_completion_tokens=true override in the library", "boundary": "The teaching demo learns the token field from a 400; the library does not use that same learning loop."}, {"family": "Mistral", "mapping": "Message reducer; no default token limit for detected Mistral models", "boundary": "The reducer folds a following user message into a preceding tool result; model capability remains deployment-specific."}, {"family": "Moonshot / Kimi", "mapping": "thinking enabled/disabled object; reasoning content can be returned", "boundary": "Code notes record that a disabled setting did not suppress thinking in an earlier Foundry probe."}, {"family": "OpenAI GPT-5 / o-series", "mapping": "max_completion_tokens and reasoning_effort", "boundary": "Accepted effort levels and sampling controls vary. Current token detection does not cover every future GPT family."}, {"family": "OpenAI legacy chat / GPT-4o", "mapping": "max_tokens; no derived reasoning control", "boundary": "A raw unsupported reasoning parameter can still be rejected."}, {"family": "Router", "mapping": "reasoning_effort forwarded by the current mapping", "boundary": "Record the requested deployment and the actual returned model; routing can change what behavior is observed."}, {"family": "xAI / Grok", "mapping": "reasoning_effort; reasoning token usage where returned", "boundary": "The mapping does not promise that effort=none disables reasoning or that internal reasoning text is exposed."}]');
